"use client";

import { Fragment, useEffect, useRef, useState, type RefObject } from "react";
import { gsap, useGSAP } from "@/lib/gsap";
import { cn } from "@/lib/utils";
import { surahDataUrl } from "@/lib/surahs";

/** [Uthmani text, start ms, end ms] – generated by scripts/build-surah-data.mjs */
type Word = [text: string, start: number, end: number];
type Verse = {
  n: number;
  from: number;
  to: number;
  words: Word[];
  translation: string;
};
type SurahData = { number: number; audio: string; verses: Verse[] };

const TRANSLATION_KEY = "quran-ayat-play:translation";

const cache = new Map<number, Promise<SurahData>>();
function loadSurah(n: number) {
  let p = cache.get(n);
  if (!p) {
    p = fetch(surahDataUrl(n)).then((r) => {
      if (!r.ok) throw new Error(`Surah ${n} data: ${r.status}`);
      return r.json() as Promise<SurahData>;
    });
    p.catch(() => cache.delete(n)); // allow a retry next time
    cache.set(n, p);
  }
  return p;
}

const AR_DIGITS = "٠١٢٣٤٥٦٧٨٩";
const toArabicDigits = (n: number) =>
  String(n).replace(/\d/g, (d) => AR_DIGITS[Number(d)]);

/** Index of the verse playing at `ms` (last verse that has started), or -1 before the first. */
function findVerse(verses: Verse[], ms: number) {
  let lo = 0;
  let hi = verses.length - 1;
  let found = -1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (verses[mid].from <= ms) {
      found = mid;
      lo = mid + 1;
    } else hi = mid - 1;
  }
  return found;
}

/**
 * Synced lyrics card: every ayah of the surah in a list that glides so the ayah being
 * recited stays centred. Its words light up one by one; tap any ayah to jump to it.
 */
export function AyahLyrics({
  surah,
  audioRef,
  className,
}: {
  surah: number | null;
  audioRef: RefObject<HTMLAudioElement | null>;
  className?: string;
}) {
  const cardRef = useRef<HTMLElement>(null);
  const viewportRef = useRef<HTMLDivElement>(null);
  const listRef = useRef<HTMLOListElement>(null);
  const counterRef = useRef<HTMLParagraphElement>(null);
  const dataRef = useRef<SurahData | null>(null);
  const verseRef = useRef(-1);
  const wordRef = useRef(-2);

  const [data, setData] = useState<SurahData | null>(null);
  const [failed, setFailed] = useState<number | null>(null);
  const [showTranslation, setShowTranslation] = useState(false);

  // Data for the current surah only; stale data from the previous surah is ignored.
  const active = data && data.number === surah ? data : null;

  useEffect(() => {
    if (surah === null) return;
    let alive = true;
    loadSurah(surah)
      .then((d) => alive && setData(d))
      .catch(() => alive && setFailed(surah));
    return () => {
      alive = false;
    };
  }, [surah]);

  const toggleTranslation = () => {
    const next = !showTranslation;
    setShowTranslation(next);
    try {
      localStorage.setItem(TRANSLATION_KEY, next ? "1" : "0");
    } catch {}
  };

  /** Glide the list so `el` sits in the middle of the card. */
  const centerOn = (el: Element | null | undefined, instant = false) => {
    const list = listRef.current;
    const viewport = viewportRef.current;
    if (!el || !list || !viewport) return;
    const r = el.getBoundingClientRect();
    const mid = r.top - list.getBoundingClientRect().top + r.height / 2;
    gsap.to(list, {
      y: viewport.clientHeight / 2 - mid,
      duration: instant ? 0 : 0.9,
      ease: "power3.out",
      overwrite: true,
    });
  };
  const verseEl = (i: number) =>
    listRef.current?.querySelector<HTMLElement>(`[data-verse="${i}"]`);

  // Restore the translation preference (after hydration, so server and client HTML match).
  useGSAP(() => {
    try {
      if (localStorage.getItem(TRANSLATION_KEY) === "1")
        setShowTranslation(true);
    } catch {}
  });

  // Follow the audio every frame: move to the current ayah and light up the word being recited.
  useGSAP(() => {
    const tick = () => {
      const d = dataRef.current;
      const audio = audioRef.current;
      const list = listRef.current;
      if (!d || !audio || !list) return;
      const ms = audio.currentTime * 1000;

      const i = findVerse(d.verses, ms);
      if (i !== verseRef.current) {
        const prev = verseEl(verseRef.current);
        if (prev) prev.dataset.current = "false";
        verseRef.current = i;
        wordRef.current = -2;
        const cur = verseEl(i);
        if (cur) cur.dataset.current = "true";
        if (counterRef.current)
          counterRef.current.textContent =
            i >= 0
              ? `Ayah ${d.verses[i].n} of ${d.verses.length}`
              : `${d.verses.length} ayahs`;
        centerOn(cur ?? verseEl(0));
        // Re-centre once the ayah has finished growing to full size (0.5s CSS transition).
        gsap.delayedCall(0.55, () => {
          if (verseRef.current === i) centerOn(cur ?? verseEl(0));
        });
      }
      if (i < 0) return;

      const v = d.verses[i];
      let w = -1;
      for (let k = 0; k < v.words.length && v.words[k][1] <= ms; k++) w = k;
      if (w === wordRef.current) return;
      wordRef.current = w;
      const li = verseEl(i);
      if (!li) return;
      const spans = li.querySelectorAll<HTMLElement>("[data-word]");
      spans.forEach((el, k) => {
        el.dataset.state = k < w ? "past" : k === w ? "active" : "future";
      });
      // Very long ayahs: follow the active word instead of the ayah's centre.
      const viewport = viewportRef.current;
      if (viewport && li.offsetHeight > viewport.clientHeight * 0.6 && spans[w])
        centerOn(spans[w]);
    };
    gsap.ticker.add(tick);
    return () => gsap.ticker.remove(tick);
  });

  // New surah: start from the top, and let the ayahs rise in.
  useGSAP(
    () => {
      dataRef.current = active;
      verseRef.current = -1;
      wordRef.current = -2;
      if (counterRef.current)
        counterRef.current.textContent = active
          ? `${active.verses.length} ayahs`
          : "Ayahs";
      if (!active) return;
      centerOn(verseEl(0), true);
      gsap.from("[data-verse]", {
        y: 30,
        opacity: 0,
        duration: 0.7,
        ease: "power3.out",
        stagger: { amount: 0.5 },
        clearProps: "transform,opacity",
      });
    },
    { scope: cardRef, dependencies: [active] },
  );

  // Showing/hiding translations changes heights – keep the current ayah centred.
  useGSAP(
    () => {
      centerOn(verseEl(Math.max(0, verseRef.current)));
    },
    { dependencies: [showTranslation] },
  );

  useEffect(() => {
    const onResize = () =>
      centerOn(verseEl(Math.max(0, verseRef.current)), true);
    window.addEventListener("resize", onResize);
    return () => window.removeEventListener("resize", onResize);
  }, []);

  const seekTo = (v: Verse) => {
    const audio = audioRef.current;
    if (!audio || !active || audio.dataset.surah !== String(active.number))
      return;
    audio.currentTime = v.from / 1000 + 0.01;
    if (audio.paused) void audio.play().catch(() => {});
  };

  return (
    <section
      ref={cardRef}
      aria-label="Ayahs"
      className={cn(
        "relative flex flex-col overflow-hidden rounded-md border border-white/60 bg-white/55 shadow-[0_30px_60px_-30px_rgba(0,0,0,0.45)] backdrop-blur-md",
        className,
      )}
    >
      <header className="relative z-10 flex items-center justify-between gap-3 px-6 pt-5">
        <p
          ref={counterRef}
          className="text-[9px] font-medium tracking-[0.28em] text-zinc-500 uppercase"
        >
          Ayahs
        </p>
        <button
          type="button"
          aria-pressed={showTranslation}
          onClick={toggleTranslation}
          className="rounded-full border border-zinc-900/10 px-2.5 py-0.5 text-[10px] font-medium tracking-wide text-zinc-500 transition-colors hover:bg-white/70 aria-pressed:border-amber-600/30 aria-pressed:bg-amber-100/70 aria-pressed:text-amber-800"
        >
          Translation
        </button>
      </header>

      <div
        ref={viewportRef}
        // overflow-clip (not hidden): the list moves only by GSAP transforms, so the browser
        // must never scroll this box (find-in-page, scroll-into-view, focus…).
        className="relative min-h-0 flex-1 overflow-clip [mask-image:linear-gradient(transparent,black_16%,black_84%,transparent)]"
      >
        {active ? (
          <ol ref={listRef} className="px-6">
            {active.verses.map((v, i) => (
              <li
                key={v.n}
                data-verse={i}
                data-current="false"
                onClick={() => seekTo(v)}
                className="group origin-center cursor-pointer scale-[0.94] py-3 text-center opacity-35 blur-[0.4px] transition-[opacity,scale,filter] duration-500 hover:opacity-60 data-[current=true]:scale-100 data-[current=true]:opacity-100 data-[current=true]:blur-none"
              >
                <p
                  lang="ar"
                  dir="rtl"
                  className="font-quran text-[21px] leading-[44px] text-zinc-800 xl:text-[23px] xl:leading-[48px]"
                >
                  {v.words.map(([text], k) => (
                    <Fragment key={k}>
                      <span
                        data-word
                        data-state="future"
                        className="inline-block transition-[color,text-shadow,translate] duration-300 group-data-[current=true]:data-[state=active]:-translate-y-0.5 group-data-[current=true]:data-[state=active]:text-amber-600 group-data-[current=true]:data-[state=active]:[text-shadow:0_0_16px_rgba(251,191,36,0.6)] group-data-[current=true]:data-[state=future]:text-zinc-400"
                      >
                        {text}
                      </span>{" "}
                    </Fragment>
                  ))}
                  <span className="inline-block text-[0.8em] text-amber-700/70">
                    ﴿{toArabicDigits(v.n)}﴾
                  </span>
                </p>
                {showTranslation && (
                  <p className="mt-0.5 text-xs leading-5 text-zinc-700">
                    {v.translation}
                  </p>
                )}
              </li>
            ))}
          </ol>
        ) : (
          <div className="flex h-full flex-col items-center justify-center gap-3 px-8 text-center">
            <p
              lang="ar"
              dir="rtl"
              className="font-quran text-3xl leading-[2] text-zinc-400/80"
            >
              بِسْمِ ٱللَّهِ ٱلرَّحْمَـٰنِ ٱلرَّحِيمِ
            </p>
            <p className="text-sm text-zinc-500">
              {surah !== null && failed === surah
                ? "Couldn't load the ayah text."
                : surah !== null
                  ? "Loading ayahs…"
                  : "The ayahs appear here, word by word, as they're recited."}
            </p>
          </div>
        )}
      </div>
    </section>
  );
}
